// =========================================================
// CONFIGURAÇÃO DE TESTE RETROATIVO
// =========================================================
const MODO_TESTE = false; 
const DATA_TESTE = '2026-07-23'; 
const TURNO_TESTE = 1; 
// =========================================================

let targetDateStr = '';
let isTurno1 = false;

if (MODO_TESTE) {
  targetDateStr = DATA_TESTE;
  isTurno1 = (TURNO_TESTE === 1);
} else {
  const fmt = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Sao_Paulo',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    hour12: false
  });

  const parts = Object.fromEntries(fmt.formatToParts(new Date()).map(p => [p.type, p.value]));
  const year = parts.year;
  const month = parts.month;
  const day = parts.day;
  let hour = parseInt(parts.hour, 10);
  if (hour === 24) hour = 0;

  targetDateStr = `${year}-${month}-${day}`;
  isTurno1 = (hour <= 15);
}

let startISO = '';
let endISO = '';
let turnoNome = '';

if (isTurno1) {
  startISO = `${targetDateStr}T05:00:00-03:00`;
  endISO = `${targetDateStr}T13:00:00-03:00`;
  turnoNome = '05h às 13h';
} else {
  startISO = `${targetDateStr}T13:00:00-03:00`;
  endISO = `${targetDateStr}T18:00:00-03:00`;
  turnoNome = '13h às 18h';
}

const date_created_gt = new Date(startISO).getTime();
const date_created_lt = new Date(endISO).getTime();

return { 
  json: { 
    date_created_gt,
    date_created_lt,
    turno: turnoNome,
    data_referencia: targetDateStr
  } 
};

const tasks = $json.tasks || [];
const infoTurno = $('Definir Turno').first().json;

// Filtra a lista de TI (901107255265)
const tarefasValidas = tasks.filter(t => t.list.id !== '901107255265');

if (tarefasValidas.length === 0) {
    return [];
}

return tarefasValidas.map(task => {
  return {
    json: {
      turno: infoTurno.turno,
      data_ref: infoTurno.data_referencia,
      task_id: task.id,
      name: task.name,
      description: task.description ? task.description.substring(0, 300) : '',
      status: task.status,
      creator: task.creator,
      date_created: task.date_created
    }
  };
});

const tasks = $('Filtrar e Mapear').all().map(i => i.json);
const commentsResults = $input.all().map(i => i.json);
const infoTurno = tasks.length > 0 ? tasks[0] : {};

let totalAbertos = tasks.length;
let concluidos = 0;
let emAndamento = 0;
let naoIniciados = 0;

let somaSlaMinutos = 0;
let tarefasComSla = 0;

tasks.forEach((task, index) => {
    const statusType = task.status ? (task.status.type || '') : '';
    const statusName = task.status ? (task.status.status || '').toLowerCase() : '';

    if (statusType === 'done' || statusType === 'closed') {
        concluidos++;
    } else if (statusName.includes('não iniciado') || statusName.includes('nao iniciado') || statusType === 'unstarted') {
        naoIniciados++;
    } else {
        emAndamento++;
    }

    const comments = commentsResults[index] ? (commentsResults[index].comments || []) : [];
    if (comments.length > 0) {
        const creatorId = task.creator ? task.creator.id : null;
        const respostasAnalistas = comments.filter(c => c.user && c.user.id !== creatorId);

        if (respostasAnalistas.length > 0) {
            const sortedComments = respostasAnalistas.sort((a, b) => parseInt(a.date) - parseInt(b.date));
            const firstComment = sortedComments[0];
            const slaMinutos = Math.round((parseInt(firstComment.date) - parseInt(task.date_created)) / 60000);

            if (slaMinutos >= 0) {
                somaSlaMinutos += slaMinutos;
                tarefasComSla++;
            }
        }
    }
});

let slaFormatado = "Sem respostas";
if (tarefasComSla > 0) {
    const slaMedia = Math.round(somaSlaMinutos / tarefasComSla);
    const h = Math.floor(slaMedia / 60);
    const m = slaMedia % 60;
    slaFormatado = h > 0 ? `${h}h ${m}m` : `${m}m`;
}

const pctResolvidos = totalAbertos > 0 ? Math.round((concluidos / totalAbertos) * 100) : 0;
const pctConcluidos = pctResolvidos;
const pctEmAndamento = totalAbertos > 0 ? Math.round((emAndamento / totalAbertos) * 100) : 0;
const pctNaoIniciados = totalAbertos > 0 ? Math.round((naoIniciados / totalAbertos) * 100) : 0;

return {
    json: {
        turno: infoTurno.turno,
        data_referencia: infoTurno.data_ref,
        metricas: {
            total_abertos: totalAbertos,
            sla_media: slaFormatado,
            pct_resolvidos: pctResolvidos,
            concluidos,
            pct_concluidos: pctConcluidos,
            em_andamento: emAndamento,
            pct_em_andamento: pctEmAndamento,
            nao_iniciados: naoIniciados,
            pct_nao_iniciados: pctNaoIniciados
        },
        tarefas: tasks.map(t => ({ titulo: t.name, descricao: t.description }))
    }
};
